----------------------------------------------------------------------
-- VoidProf — Lockpicking (WoW Forever, rogues), 2026-11-17
--
-- The user: "need to add lockpicking in professions and add this data" (a 1-300 footlocker route they
-- found). The route below is theirs, in our own words, checked line by line before it shipped:
--   * the skill each container needs = WoW Forever's own Lock table (LockpickData.lua, generated by
--     tools/cmd/vprof-lockpick; every bracket in their route matched it);
--   * where they spawn = VoidDB's spawn data per container version. Two places were corrected from it:
--     the 110 Battered Footlockers in Stonetalon sit at the east end of Windshear Mine (72-74, 59-63), the
--     ones around 63, 48 are the 70 version; Tyr's Hand's Scarlet Footlockers are at 68-77, 65-74.
--   * Blackrock Depths' Shadowforge Gate and East Garrison Door need 250 (the same Lock table).
-- "Points until" (upTo) is the route's own advice where to move on; the tab also learns where YOUR skill-ups
-- happen (VoidProfCharDB.lockLog: the container's required skill and your skill at each point), so a measured
-- answer can replace it later.
----------------------------------------------------------------------
if (select(4, GetBuildInfo()) or 0) >= 100000 then return end   -- WoW Forever only
local DATA = VoidProf and VoidProf.LockpickData
if not DATA then return end

local LP = {}
VoidProf.Lockpick = LP

local SKILL_LINE = 633   -- Lockpicking
local PICK_LOCK = 1804   -- Pick Lock (measured on Forever: its combat log has START/FAILED, no success)

-- The route: { req, upTo, name, map, side, where } (side: "H" / "A" / nil = both)
local ROUTE = {
    { 1,   100, "Buccaneer's Strongbox",  1413, nil, "Below deck in the wrecked pirate ship south of Ratchet. They come back fast, and keep giving points to 100." },
    { 1,   100, "Practice Lockbox",       1433, "A", "In and around Alther's Mill, north of Lake Everstill. Fast to come back." },
    { 70,  110, "Waterlogged Footlocker", 1440, nil, "Zoram Strand: in the shallows along the shore." },
    { 70,  110, "Waterlogged Footlocker", 1433, nil, "On the bottom of Lake Everstill." },
    { 70,  110, "Battered Footlocker",    1424, nil, "Durnholde Keep, the lower barracks (the 70 and 110 ones are mixed in the keep)." },
    { 70,  110, "Battered Footlocker",    1437, nil, "The murloc camps northeast of Menethil Harbor." },
    { 70,  110, "Battered Footlocker",    1442, nil, "Windshear Crag and the west part of Windshear Mine." },
    { 110, 150, "Battered Footlocker",    1424, nil, "Durnholde Keep: the upper ring, the broken castle and the western tower." },
    { 110, 150, "Battered Footlocker",    1437, nil, "The murloc camps northeast of Menethil Harbor (mixed in with the 70 ones)." },
    { 110, 150, "Battered Footlocker",    1442, nil, "The east end of Windshear Mine. Indoors, few other players." },
    { 150, 175, "Battered Footlocker",    1418, nil, "Angor Fortress, upstairs." },
    { 150, 175, "Waterlogged Footlocker", 1443, nil, "Sar'theris Strand: the shallow water west of Ethel Rethor (not down by Shadowprey Village)." },
    { 175, 225, "Dented Footlocker",      1418, nil, "Angor Fortress, downstairs. Level 40-43 Dark Iron guards; pickpocket them for Sturdy Junkboxes too." },
    { 175, 225, "Mossy Footlocker",       1435, nil, "Around the Temple of Atal'Hakkar and the Pool of Tears." },
    { 175, 225, "Mossy Footlocker",       1443, nil, "Sar'theris Strand, the deeper water." },
    { 200, 225, "Dented Footlocker",      1427, nil, "The Slag Pit, lower floor: stay down there until 225." },
    { 225, 250, "Dented Footlocker",      1427, nil, "The Slag Pit, the upper barracks." },
    { 225, 250, "Dented Footlocker",      1446, nil, "Lost Rigger Cove, on the east coast." },
    { 225, 250, "Mossy Footlocker",       1447, nil, "The Bay of Storms: underwater and along the coastal ruins." },
    { 250, 265, "BRD doors",              nil,  nil, "Blackrock Depths: the Shadowforge Gate and the East Garrison Door (need 250). Stealth in, pick them, reset the instance. Players say the points stop around 265." },
    { 250, 300, "Scarlet Footlocker",     1423, nil, "Tyr's Hand: in the buildings and the courtyard, among elite Scarlets (pickpocket them for Heavy Junkboxes too)." },
}
LP.ROUTE = ROUTE

local ZONE = {
    [1413] = "The Barrens", [1433] = "Redridge Mountains", [1440] = "Ashenvale", [1424] = "Hillsbrad Foothills",
    [1437] = "Wetlands", [1442] = "Stonetalon Mountains", [1418] = "Badlands", [1443] = "Desolace",
    [1435] = "Swamp of Sorrows", [1427] = "Searing Gorge", [1446] = "Tanaris", [1447] = "Azshara",
    [1423] = "Eastern Plaguelands",
}

-- every spot of this container (name + required skill) on this map: { {x, y}, ... }
local function spotsOf(name, req, map)
    local out = {}
    for _, c in pairs(DATA) do
        if c.name == name and c.req == req and c.spots[map] then
            local s = c.spots[map]
            for i = 1, #s, 2 do out[#out + 1] = { s[i], s[i + 1] } end
        end
    end
    return out
end
LP.SpotsOf = spotsOf

local function charDB()
    VoidProfCharDB = VoidProfCharDB or {}
    VoidProfCharDB.lockLog = VoidProfCharDB.lockLog or {}
    return VoidProfCharDB
end

-- Your Lockpicking: rank, max (nil while unknown). C_SkillInfo by the skill line, then the list by name, then
-- the last "Your skill in Lockpicking has increased to N" seen (saved).
function LP:Skill()
    local ok, info = pcall(function()
        return C_SkillInfo and C_SkillInfo.GetSkillLineInfoByID and C_SkillInfo.GetSkillLineInfoByID(SKILL_LINE)
    end)
    if ok and type(info) == "table" and type(info.rank) == "number" and info.rank > 0 then
        return info.rank, info.maxRank
    end
    if C_SkillInfo and C_SkillInfo.GetNumSkillLines and C_SkillInfo.GetSkillLineInfo then
        local okN, n = pcall(C_SkillInfo.GetNumSkillLines)
        for i = 1, (okN and tonumber(n) or 0) do
            local okI, a = pcall(C_SkillInfo.GetSkillLineInfo, i)
            if okI and type(a) == "table" and a.name == "Lockpicking" and type(a.rank) == "number" then return a.rank, a.maxRank end
        end
    end
    local s = charDB().lockSkill
    return s, nil
end

local function isRogue() local _, c = UnitClass("player"); return c == "ROGUE" end
LP.IsRogue = isRogue

-- where a route step stands for you: "done" (past its points), "now" (gives points), "later"
function LP:State(step, skill)
    if not skill then return "later" end
    if skill >= step[2] then return "done" end
    if skill >= step[1] then return "now" end
    return "later"
end

----------------------------------------------------------------------
-- Learning where your points come from: the container you walked up to (its object ID -> required skill)
-- and your skill when a point came
----------------------------------------------------------------------
-- lastBox = { req, name, t } of the container highlighted now (cleared when the highlight moves off it);
-- pickBox = the one you were facing when Pick Lock started, lastPick = GetTime() of that cast. A lockbox
-- picked in your bags has no highlighted container, so it never credits a chest you passed (Sol review).
local lastBox, pickBox, lastPick
local function onSkillUp(newRank)
    local db = charDB()
    db.lockSkill = newRank
    local box = pickBox
    -- only a point from picking: you cast Pick Lock on that container within the last minute
    if box and lastPick and GetTime() - lastPick < 60 then
        local log = db.lockLog
        log[#log + 1] = { req = box.req, at = newRank, t = time() }
        while #log > 400 do table.remove(log, 1) end
    end
end

-- the highest skill a point came at from a container of this required skill (your own picks), or nil
function LP:LearnedTop(req)
    local top
    for _, e in ipairs(charDB().lockLog) do
        if e.req == req and (not top or e.at > top) then top = e.at end
    end
    return top
end

local ev = CreateFrame("Frame")
ev:RegisterEvent("PLAYER_SOFT_INTERACT_CHANGED")
ev:RegisterEvent("CHAT_MSG_SKILL")
ev:RegisterEvent("SKILL_LINES_CHANGED")
ev:RegisterUnitEvent("UNIT_SPELLCAST_START", "player")
ev:RegisterUnitEvent("UNIT_SPELLCAST_SENT", "player")
local sentTarget   -- what the last Pick Lock was cast on, by name ("" / nil when the game doesn't say)
ev:SetScript("OnEvent", function(_, event, a1, a2, a3, a4)
    if event == "PLAYER_SOFT_INTERACT_CHANGED" then
        if issecretvalue and issecretvalue(a2) then return end
        if type(a2) ~= "string" then lastBox = nil; return end   -- the highlight left every object
        local m = a2:match("^GameObject%-%d+%-%d+%-%d+%-%d+%-(%d+)%-")
        local c = m and DATA[tonumber(m)]
        lastBox = c and { req = c.req, name = c.name, t = GetTime() } or nil
    elseif event == "UNIT_SPELLCAST_SENT" then
        -- (unit, target name, castGUID, spellID): a lockbox picked in your bags names the box item, so it
        -- doesn't credit a chest still highlighted next to you (Sol review)
        if a4 == PICK_LOCK then
            sentTarget = (type(a2) == "string" and not (issecretvalue and issecretvalue(a2))) and a2 or nil
        end
    elseif event == "UNIT_SPELLCAST_START" then
        if a3 == PICK_LOCK then
            lastPick = GetTime()
            pickBox = lastBox and GetTime() - lastBox.t < 30 and lastBox or nil
            if pickBox and sentTarget and sentTarget ~= "" and sentTarget ~= pickBox.name then pickBox = nil end
            sentTarget = nil
        end
    elseif event == "CHAT_MSG_SKILL" then
        if type(a1) ~= "string" or (issecretvalue and issecretvalue(a1)) then return end
        local n = a1:match("^Your skill in Lockpicking has increased to (%d+)")
        if n then onSkillUp(tonumber(n)) end
    elseif event == "SKILL_LINES_CHANGED" then
        local r = LP:Skill()
        if r then charDB().lockSkill = r end
    end
    if LP.tab and LP.tab:IsVisible() then LP:RefreshTab() end
end)

----------------------------------------------------------------------
-- The tab
----------------------------------------------------------------------
local ROW_H = 30

local function go(step)
    if not step[4] then return end
    local spots = spotsOf(step[3], step[1], step[4])
    if #spots == 0 then return end
    -- the spot nearest you when you're in that zone, else the middle of them
    local best = spots[1]
    local here = C_Map.GetBestMapForUnit("player")
    local pos = here == step[4] and C_Map.GetPlayerMapPosition(here, "player")
    if pos then
        local px, py = pos:GetXY()
        local bd
        for _, s in ipairs(spots) do
            local d = (s[1] - px) ^ 2 + (s[2] - py) ^ 2
            if not bd or d < bd then best, bd = s, d end
        end
    else
        local sx, sy = 0, 0
        for _, s in ipairs(spots) do sx, sy = sx + s[1], sy + s[2] end
        local cx, cy = sx / #spots, sy / #spots
        local bd
        for _, s in ipairs(spots) do
            local d = (s[1] - cx) ^ 2 + (s[2] - cy) ^ 2
            if not bd or d < bd then best, bd = s, d end
        end
    end
    if VoidProf.Knowledge and VoidProf.Knowledge.Waypoint then
        VoidProf.Knowledge:Waypoint({ map = step[4], x = best[1] * 100, y = best[2] * 100, name = step[3] })
    end
end

function LP:BuildTab(parent)
    local f = CreateFrame("Frame", nil, parent)
    f:SetAllPoints()
    local head = f:CreateFontString(nil, "OVERLAY")
    VoidUI:SetFont(head, 12, "")
    head:SetPoint("TOPLEFT", 14, -8)
    local sub = f:CreateFontString(nil, "OVERLAY")
    VoidUI:SetFont(sub, 9, "")
    sub:SetPoint("TOPLEFT", head, "BOTTOMLEFT", 0, -3)
    sub:SetPoint("RIGHT", f, "RIGHT", -14, 0)
    sub:SetJustifyH("LEFT")
    sub:SetTextColor(0.6, 0.6, 0.66)
    local scroll = CreateFrame("ScrollFrame", nil, f, "UIPanelScrollFrameTemplate")
    scroll:SetPoint("TOPLEFT", 8, -46)
    scroll:SetPoint("BOTTOMRIGHT", -28, 6)
    local child = CreateFrame("Frame", nil, scroll)
    local pw = parent.GetWidth and parent:GetWidth() or 0
    child:SetSize(math.max(500, (pw or 0) - 44), #ROUTE * ROW_H)   -- the window grows with its tabs
    scroll:SetScrollChild(child)
    local rows = {}
    for i, step in ipairs(ROUTE) do
        local r = CreateFrame("Button", nil, child)
        r:SetHeight(ROW_H - 2)
        r:SetPoint("TOPLEFT", 0, -(i - 1) * ROW_H)
        r:SetPoint("RIGHT", child, "RIGHT", 0, 0)
        r.bg = r:CreateTexture(nil, "BACKGROUND")
        r.bg:SetAllPoints()
        r.bg:SetColorTexture(1, 1, 1, 0.04)
        r.top = r:CreateFontString(nil, "OVERLAY")
        VoidUI:SetFont(r.top, 10, "")
        r.top:SetPoint("TOPLEFT", 6, -2)
        r.top:SetPoint("RIGHT", r, "RIGHT", -6, 0)
        r.top:SetJustifyH("LEFT")
        r.top:SetWordWrap(false)
        r.where = r:CreateFontString(nil, "OVERLAY")
        VoidUI:SetFont(r.where, 9, "")
        r.where:SetPoint("TOPLEFT", r.top, "BOTTOMLEFT", 0, -1)
        r.where:SetPoint("RIGHT", r, "RIGHT", -6, 0)
        r.where:SetJustifyH("LEFT")
        r.where:SetWordWrap(false)
        r:SetScript("OnClick", function() go(step) end)
        r:SetScript("OnEnter", function(self)
            GameTooltip:SetOwner(self, "ANCHOR_RIGHT")
            GameTooltip:AddLine(("%s  (needs Lockpicking %d)"):format(step[3], step[1]), 1, 1, 1)
            GameTooltip:AddLine(step[6], 0.85, 0.85, 0.85, true)
            if step[4] then
                local n = #spotsOf(step[3], step[1], step[4])
                GameTooltip:AddLine(("%d spots in %s. Click for a waypoint to the nearest."):format(n, ZONE[step[4]] or "the zone"), 0.5, 0.8, 1, true)
            end
            local top = LP:LearnedTop(step[1])
            if top then GameTooltip:AddLine(("Your last point from these came at %d."):format(top), 0.6, 1, 0.6) end
            GameTooltip:Show()
        end)
        r:SetScript("OnLeave", function() GameTooltip:Hide() end)
        rows[i] = r
    end
    f.head, f.sub, f.rows, f.scroll = head, sub, rows, scroll
    LP.tab = f
    parent._lockpick = f
    f:SetScript("OnShow", function() LP:RefreshTab() end)
end

function LP:RefreshTab()
    local f = LP.tab
    if not f then return end
    local skill, max = LP:Skill()
    local side = UnitFactionGroup("player") == "Alliance" and "A" or "H"
    if not isRogue() then
        f.head:SetText("Lockpicking")
        f.sub:SetText("Lockpicking is a rogue skill. Log in on a rogue to see where to level it.")
    elseif skill then
        f.head:SetText(("Lockpicking |cffffd200%d|r%s"):format(skill, max and ("/" .. max) or ""))
        f.sub:SetText("Green: gives you points now. Click a line for a waypoint. Max goes up 5 per level (Pick Lock).")
    else
        f.head:SetText("Lockpicking")
        f.sub:SetText("Your skill shows after your next Lockpicking point. Click a line for a waypoint.")
    end
    local firstNow
    for i, step in ipairs(ROUTE) do
        local r = f.rows[i]
        local st = LP:State(step, skill)
        local other = step[5] and step[5] ~= side
        local where = step[4] and ZONE[step[4]] or "Blackrock Depths"
        r.top:SetText(("%s|cff%s%d-%d|r  %s  |cff8a8a94%s|r"):format(
            st == "now" and "|cff33ff33>|r " or "  ",
            st == "now" and "33ff33" or st == "done" and "6a6a72" or "ffd200", step[1], step[2],
            st == "done" and ("|cff6a6a72" .. step[3] .. "|r") or step[3], where .. (other and " (other faction)" or "")))
        r.where:SetText(step[6])
        r.where:SetTextColor(st == "done" and 0.42 or 0.72, st == "done" and 0.42 or 0.72, st == "done" and 0.46 or 0.78)
        r.bg:SetColorTexture(st == "now" and 0.2 or 1, st == "now" and 1 or 1, st == "now" and 0.2 or 1, st == "now" and 0.08 or 0.03)
        if st == "now" and not firstNow then firstNow = i end
    end
    -- the first line that gives points in view
    if firstNow and not f.scrolled then
        f.scrolled = true
        f.scroll:SetVerticalScroll(math.max(0, (firstNow - 2) * ROW_H))
    end
end
